$ErrorActionPreference = 'Stop'
$root = 'C:\dev\nial_diary'
$path = Join-Path $root 'lib\main.dart'
$expected = '4082B8413D1828E6A8CFCD3B43FC2FEDE0DD5390A499647204F16CFB3F8F95DE'
$actual = (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash
if ($actual -ne $expected) {
  throw 'main.dart differs from the uploaded source. No files changed. Send the current main.dart; do not bypass this check.'
}
$backup = Join-Path $root ('backups\before_photos_' + (Get-Date -Format 'yyyyMMdd_HHmmss_fff'))
New-Item -ItemType Directory -Path $backup -Force | Out-Null
Copy-Item -LiteralPath $path -Destination (Join-Path $backup 'main.dart.bak')
$encoded = @'

'@
try {
  [IO.File]::WriteAllBytes($path, [Convert]::FromBase64String($encoded.Trim()))
} catch {
  Copy-Item -LiteralPath (Join-Path $backup 'main.dart.bak') -Destination $path -Force
  throw
}
Write-Host 'SUCCESS: photos installed in main.dart. Run dart format and flutter analyze.'
Write-Host "Source backup: $backup"
